    enemies = observation.get('enemies', [])
    resources = observation.get('resources', [])
    territory = observation.get('territory', [])

    # Helper to compute Manhattan distance
    def dist(a, b):
        return abs(a[0] - b[0]) + abs(a[1] - b[1])

    # Coordinates
    x, y = own_pos

    # Initialize move to stay still
    dx, dy = 0, 0

    # Find closest resource
    closest_res = None
    min_res_dist = float('inf')
    for res in resources:
        res_pos = res.get('position', (0, 0))
        d = dist(own_pos, res_pos)
        if d < min_res_dist:
            min_res_dist = d
