    if closest_res and (min_enemy_dist > 1):
        dx = 0
        dy = 0
        if closest_res[0] > x:
            dx = 1
        elif closest_res[0] < x:
            dx = -1
        if closest_res[1] > y:
            dy = 1
        elif closest_res[1] < y:
            dy = -1
        # Prioritize axis with larger distance
        if abs(closest_res[0] - x) > abs(closest_res[1] - y):
            dy = 0
        else:
            dx = 0
    # Else if enemy nearby, pursue or evade
    elif closest_enemy and min_enemy_dist <= 3:
        # Simple fleeing behavior
        if closest_enemy[0] > x:
            dx = -1
        elif closest_enemy[0] < x:
            dx = 1
        else:
            dx = 0
        if closest_enemy[1] > y:
            dy = -1
        elif closest_enemy[1] < y:
